import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) { return twMerge(clsx(inputs)); }
export function formatCurrency(n: number) { return "₹" + n.toLocaleString("en-IN"); }
export function truncateText(s: string, len: number) { return s.length > len ? s.slice(0, len) + "…" : s; }
