// src/store/useStore.ts
import { create } from "zustand";
import type { BriefState, ShortlistState } from "@/types";
interface AppStore extends BriefState, ShortlistState {
  setStep: (s: BriefState["step"]) => void;
  toggleService: (s: BriefState["services"][number]) => void;
  setBudget: (n: number) => void;
  addShortlist: (id: string) => void;
  removeShortlist: (id: string) => void;
}
export const useApp = create<AppStore>((set) => ({
  step: 1, businessType: "", services: [], budget: 500000, kickoff: "",
  ids: [],
  setStep: (step) => set({ step }),
  toggleService: (s) => set((st) => ({ services: st.services.includes(s) ? st.services.filter(x => x !== s) : [...st.services, s] })),
  setBudget: (budget) => set({ budget }),
  addShortlist: (id) => set((st) => ({ ids: [...new Set([...st.ids, id])] })),
  removeShortlist: (id) => set((st) => ({ ids: st.ids.filter(x => x !== id) })),
}));
