// src/types.ts
export type ButtonVariant = "primary" | "secondary" | "ghost";
export type PlanInterval = "monthly" | "annual";
export type ApiLang = "curl" | "node" | "python";

export interface NavItem { label: string; href: string; }
export interface FeatureCard { id: string; title: string; desc: string; icon: string; }
export interface Plan { id: string; name: string; monthly: number; annual: number; features: string[]; cta: ButtonVariant; }
export interface ContactState {
  service: string;
  budget: number;
  email: string;
  step: number;
}
export interface PricingState {
  interval: PlanInterval;
  setInterval: (i: PlanInterval) => void;
}
