// src/types.ts
export type ProductCategory = "pdf" | "video" | "software" | "membership";
export type ButtonVariant = "primary" | "secondary" | "ghost";
export interface Product {
  id: string;
  title: string;
  price: number;
  category: ProductCategory;
  creator: string;
  description: string;
  thumbnail: string;
}
export interface CartItem extends Product { quantity: number; }
export type MembershipTier = "fan" | "supporter" | "patron";
export interface MembershipPlan {
  tier: MembershipTier;
  priceMonthly: number;
  features: string[];
}
export interface ContactFormState {
  service: string;
  budget: number;
  email: string;
  message: string;
  step: 1 | 2 | 3;
}
