import { create } from "zustand";
import type { CartItem, Product } from "@/types";
type State = {
  cart: CartItem[];
  wishlist: string[];
  addToCart: (p: Product) => void;
  toggleWish: (id: string) => void;
};
export const useStore = create<State>((set) => ({
  cart: [],
  wishlist: [],
  addToCart: (p) => set((s) => {
    const found = s.cart.find((c) => c.product.id === p.id);
    if (found) return { cart: s.cart.map((c) => c.product.id===p.id ? {...c,qty:c.qty+1}:c) };
    return { cart: [...s.cart, { product: p, qty: 1 }] };
  }),
  toggleWish: (id) => set((s) => ({ wishlist: s.wishlist.includes(id) ? s.wishlist.filter(x=>x!==id) : [...s.wishlist, id] })),
}));
